<template>
  <section class="resource-card"><div class="resource-card-header"><h2>{{ title }}</h2></div><div class="chart-legend"><button v-for="(name, index) in names" :key="name" :class="{ hidden: hidden.has(index) }" @click="toggle(index)"><i :style="{ background: colors[index % colors.length] }"></i>{{ name }}<strong>{{ format(points[points.length - 1]?.values[index] || 0) }}</strong></button></div><div class="chart-area" @mouseleave="hoverIndex = undefined"><svg viewBox="0 0 640 180" role="img" :aria-label="title" @mousemove="hover"><g v-for="line in [0, 1, 2, 3]" :key="line"><line x1="58" x2="628" :y1="18 + line * 44" :y2="18 + line * 44" stroke="#363636" /><text x="50" :y="22 + line * 44" text-anchor="end">{{ format(maximum * (1 - line / 3)) }}</text></g><polyline v-for="(name, index) in names" v-show="!hidden.has(index)" :key="name" :points="linePoints(index)" :stroke="colors[index % colors.length]" fill="none" stroke-width="2" stroke-linejoin="round" /><line v-if="hoverIndex !== undefined" :x1="x(hoverIndex)" :x2="x(hoverIndex)" y1="18" y2="150" stroke="#aaa" stroke-dasharray="3 3" /><text x="58" y="174">{{ time(points[0]?.time) }}</text><text x="628" y="174" text-anchor="end">{{ time(points[points.length - 1]?.time) }}</text></svg><div v-if="hoverIndex !== undefined && points[hoverIndex]" class="chart-tooltip"><strong>{{ time(points[hoverIndex].time) }}</strong><span v-for="(name, index) in names" :key="name">{{ name }}：{{ format(points[hoverIndex].values[index] || 0) }}</span></div><div v-if="!points.length" class="chart-empty">等待采样数据…</div></div></section>
</template>
<script setup lang="ts">
import { computed, ref } from 'vue'
import { formatImageSize } from '@/utils/localImages'
const props = defineProps<{ title: string; names: string[]; points: { time: number; values: number[] }[]; unit: 'bytes' | 'percent' | 'rate' }>()
const colors = ['#58bce5', '#9c78de', '#6cca9c', '#e2ad66', '#e77e91', '#80c4bf']
const hidden = ref(new Set<number>()), hoverIndex = ref<number>()
const maximum = computed(() => Math.max(props.unit === 'percent' ? 1 : 100, ...props.points.flatMap(point => point.values.filter((_, index) => !hidden.value.has(index)))) * 1.15)
const format = (value: number) => props.unit === 'percent' ? `${value.toFixed(1)}%` : `${formatImageSize(value)}${props.unit === 'rate' ? '/秒' : ''}`
const time = (value?: number) => value ? new Date(value).toLocaleTimeString('zh-CN', { hour12: false }) : '—'
const x = (index: number) => 58 + index / Math.max(1, props.points.length - 1) * 570
const linePoints = (series: number) => props.points.map((point, index) => `${x(index)},${150 - (point.values[series] || 0) / maximum.value * 132}`).join(' ')
function toggle(index: number) { const next = new Set(hidden.value); if (next.has(index)) next.delete(index); else next.add(index); hidden.value = next }
function hover(event: MouseEvent) { const rect = (event.currentTarget as SVGElement).getBoundingClientRect(); const relative = (event.clientX - rect.left) / rect.width * 640; hoverIndex.value = props.points.length ? Math.max(0, Math.min(props.points.length - 1, Math.round((relative - 58) / 570 * Math.max(1, props.points.length - 1)))) : undefined }
</script>
<style scoped>
.chart-legend { display: flex; flex-wrap: wrap; gap: 8px 16px; min-height: 24px; }.chart-legend button { border: 0; padding: 0; display: flex; align-items: center; gap: 6px; background: transparent; color: #bbb; font: inherit; font-size: 11px; cursor: pointer; }.chart-legend button.hidden { opacity: .35; }.chart-legend i { width: 9px; height: 9px; border-radius: 2px; }.chart-legend strong { font-weight: 400; color: #ddd; margin-left: 4px; }.chart-area { position: relative; margin-top: 10px; }svg { display: block; width: 100%; height: auto; min-height: 140px; }svg text { font: 10px sans-serif; fill: #888; }.chart-tooltip { position: absolute; top: 6px; right: 20px; display: flex; flex-direction: column; gap: 3px; background: #101010e8; border: 1px solid #555; padding: 8px 12px; border-radius: 5px; font-size: 11px; pointer-events: none; }.chart-empty { position: absolute; inset: 0; display: grid; place-items: center; color: #888; }
</style>
